sys_rte_eb_etl_definition.on_after_script:
(function onAfter(source, target, importLog) {

	// Add your on after code here

})(source, target, importLog);

sys_rte_eb_etl_definition.on_before_script:
(function onBefore(source, target, importLog) {
var service =

    new x_your_scope.ServerInboundIntegrationService();

var result = service.beforeRte(source);

if (!result.proceed) {

    service.markProcessingFailed(

        source.getUniqueValue(),

        result.errors.join('; ')

    );

    /*

     * Set the release-specific abort/skip variable here.

     *

     * Examples vary by release:

     * ignore = true;

     * abort = true;

     * or context.setAbortAction(true);

     */

}

})(source, target, importLog);
